import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { MapContainer, TileLayer, useMap } from 'react-leaflet';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend
} from 'chart.js';
import 'leaflet/dist/leaflet.css';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

// Heatmap component using leaflet.heat
function HeatmapLayer({ heatData, intensity = 1 }) {
  const map = useMap();

  useEffect(() => {
    if (!window.L || !window.L.heatLayer || !heatData || heatData.length === 0) return;

    const heatLayer = window.L.heatLayer(heatData, {
      radius: 25,
      blur: 15,
      maxZoom: 17,
      max: intensity,
      gradient: {
        0.0: 'blue',
        0.3: 'cyan',
        0.5: 'lime',
        0.7: 'yellow',
        1.0: 'red'
      }
    });

    heatLayer.addTo(map);

    return () => {
      map.removeLayer(heatLayer);
    };
  }, [map, heatData, intensity]);

  return null;
}

// Main GPS Heatmap component
export default function GPSHeatmap() {
  // State management
  const [allLogs, setAllLogs] = useState([]);
  const [mapBounds, setMapBounds] = useState(null);
  const [homeLocation, setHomeLocation] = useState(null);
  const [visibleLogs, setVisibleLogs] = useState([]);
  const [heatmapData, setHeatmapData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Filter states
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [selectedLogs, setSelectedLogs] = useState([]);

  // View states
  const [showComparison, setShowComparison] = useState(false);
  const [selectedPIDs, setSelectedPIDs] = useState(['engine_rpm', 'vehicle_speed']);
  const [chartLayout, setChartLayout] = useState('combined'); // 'combined' or 'grid'
  const [availablePIDs, setAvailablePIDs] = useState([]);

  const chartColors = ['#FF4D4D', '#00E676', '#38BDF8', '#F59E0B', '#A78BFA', '#EC4899', '#8B5CF6', '#F97316'];

  // Fetch all logs on component mount
  useEffect(() => {
    const fetchLogs = async () => {
      try {
        setLoading(true);
        const response = await fetch('/api/logs');
        if (!response.ok) throw new Error(`HTTP ${response.status}`);

        const logs = await response.json();
        console.log(`[GPSHeatmap] Loaded ${logs.length} logs`);

        // Calculate home location (most frequent end point)
        const endPoints = logs
          .filter(log => log.end_lat && log.end_lon)
          .map(log => ({ lat: log.end_lat, lon: log.end_lon, count: 1 }));

        const home = findMostFrequentLocation(endPoints);
        setHomeLocation(home);

        // Set date range defaults
        if (logs.length > 0) {
          const dates = logs.map(log => new Date(log.start_timestamp * 1000));
          const minDate = new Date(Math.min(...dates));
          const maxDate = new Date(Math.max(...dates));
          setStartDate(minDate.toISOString().split('T')[0]);
          setEndDate(maxDate.toISOString().split('T')[0]);
        }

        setAllLogs(logs);
      } catch (err) {
        console.error('[GPSHeatmap] Error fetching logs:', err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchLogs();
  }, []);

  // Find most frequent location (home detection)
  const findMostFrequentLocation = (points, tolerance = 0.001) => {
    if (points.length === 0) return { lat: 44.9778, lon: -93.2650 }; // Minneapolis default

    const clusters = [];

    points.forEach(point => {
      let foundCluster = false;

      for (const cluster of clusters) {
        const distance = Math.sqrt(
          Math.pow(cluster.lat - point.lat, 2) + 
          Math.pow(cluster.lon - point.lon, 2)
        );

        if (distance < tolerance) {
          cluster.count += point.count;
          foundCluster = true;
          break;
        }
      }

      if (!foundCluster) {
        clusters.push({ ...point });
      }
    });

    // Return cluster with highest count
    return clusters.reduce((max, cluster) => 
      cluster.count > max.count ? cluster : max, clusters[0]);
  };

  // Filter logs based on date range and map bounds
  const filteredLogs = useMemo(() => {
    let filtered = allLogs;

    // Date filtering
    if (startDate && endDate) {
      const start = new Date(startDate).getTime() / 1000;
      const end = new Date(endDate).getTime() / 1000 + 86400; // End of day

      filtered = filtered.filter(log => 
        log.start_timestamp >= start && log.start_timestamp <= end
      );
    }

    // Map bounds filtering would be implemented here
    // For now, return all date-filtered logs
    return filtered;
  }, [allLogs, startDate, endDate, mapBounds]);

  // Update visible logs when filters change
  useEffect(() => {
    setVisibleLogs(filteredLogs);
  }, [filteredLogs]);

  // Generate heatmap data from visible logs
  useEffect(() => {
    const generateHeatmapData = async () => {
      if (!visibleLogs.length || !homeLocation) return;

      const heatPoints = [];

      // Process each visible log
      for (const log of visibleLogs) {
        try {
          // Fetch basic trip data (start/end points for now)
          // In a real implementation, you'd fetch full GPS track
          if (log.start_lat && log.start_lon) {
            heatPoints.push([log.start_lat, log.start_lon, 1]);
          }
          if (log.end_lat && log.end_lon) {
            heatPoints.push([log.end_lat, log.end_lon, 1]);
          }
        } catch (err) {
          console.warn(`Failed to process log ${log.log_id}:`, err);
        }
      }

      setHeatmapData(heatPoints);
    };

    generateHeatmapData();
  }, [visibleLogs, homeLocation]);

  // Handle log selection for comparison
  const handleLogSelect = useCallback((log, selected) => {
    setSelectedLogs(prev => {
      if (selected) {
        return prev.length < 10 ? [...prev, log] : prev; // Max 10 logs
      } else {
        return prev.filter(l => l.log_id !== log.log_id);
      }
    });
  }, []);

  // Start comparison mode
  const handleCompareNow = useCallback(async () => {
    if (selectedLogs.length === 0) {
      alert('Please select at least one log to compare');
      return;
    }

    setLoading(true);
    try {
      // Fetch data for selected logs
      const logDataPromises = selectedLogs.slice(0, 10).map(async log => {
        const response = await fetch(`/api/logs/${log.log_id}/data`);
        if (!response.ok) throw new Error(`Failed to fetch log ${log.log_id}`);
        const data = await response.json();
        return { ...log, data: data.data, columns: data.columns };
      });

      const logsWithData = await Promise.all(logDataPromises);

      // Extract available PIDs from first log
      if (logsWithData.length > 0 && logsWithData[0].columns) {
        setAvailablePIDs(logsWithData[0].columns);
      }

      setSelectedLogs(logsWithData);
      setShowComparison(true);
    } catch (err) {
      console.error('Error loading comparison data:', err);
      alert('Error loading log data for comparison');
    } finally {
      setLoading(false);
    }
  }, [selectedLogs]);

  // Render comparison charts
  const renderComparison = () => {
    if (!showComparison || selectedLogs.length === 0) return null;

    if (chartLayout === 'grid') {
      return (
        <div className="fixed inset-0 bg-gray-900 z-50 overflow-auto">
          {/* Grid Header */}
          <div className="bg-gray-800 p-4 border-b border-gray-700">
            <div className="flex justify-between items-center">
              <h2 className="text-xl font-bold text-cyan-400">
                Trip Comparison Grid - {selectedLogs.length} Logs
              </h2>
              <div className="flex gap-2">
                <button
                  onClick={() => setChartLayout('combined')}
                  className="bg-blue-600 hover:bg-blue-700 px-4 py-2 rounded"
                >
                  Combined View
                </button>
                <button
                  onClick={() => setShowComparison(false)}
                  className="bg-gray-600 hover:bg-gray-700 px-4 py-2 rounded"
                >
                  Back to Map
                </button>
              </div>
            </div>
          </div>

          {/* Grid Layout */}
          <div className="p-4 grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-4">
            {selectedLogs.map((log, index) => (
              <div key={log.log_id} className="bg-gray-800 rounded-lg p-3 min-h-[300px]">
                <h3 className="text-sm font-semibold text-gray-300 mb-2 truncate">
                  {log.file_name}
                </h3>
                <div className="h-[250px]">
                  <Line
                    options={{
                      responsive: true,
                      maintainAspectRatio: false,
                      animation: false,
                      plugins: { legend: { display: false } },
                      scales: {
                        x: { ticks: { color: '#9CA3AF', display: false } },
                        y: { ticks: { color: '#9CA3AF' } }
                      }
                    }}
                    data={{
                      labels: log.data?.map((_, i) => i) || [],
                      datasets: selectedPIDs.slice(0, 2).map((pid, pidIndex) => ({
                        label: pid,
                        data: log.data?.map(row => row[pid]) || [],
                        borderColor: chartColors[pidIndex],
                        pointRadius: 0,
                        borderWidth: 2
                      }))
                    }}
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      );
    }

    // Combined view
    return (
      <div className="fixed inset-4 bg-gray-900 rounded-lg shadow-2xl z-50 flex flex-col">
        {/* Combined Header */}
        <div className="bg-gray-800 p-4 rounded-t-lg border-b border-gray-700">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-bold text-cyan-400">
              Trip Comparison - {selectedLogs.length} Logs
            </h2>
            <div className="flex gap-2">
              <button
                onClick={() => setChartLayout('grid')}
                className="bg-purple-600 hover:bg-purple-700 px-4 py-2 rounded"
              >
                Grid View
              </button>
              <button
                onClick={() => setShowComparison(false)}
                className="bg-gray-600 hover:bg-gray-700 px-4 py-2 rounded"
              >
                Back to Map
              </button>
            </div>
          </div>

          {/* PID Selectors */}
          <div className="flex gap-4">
            {selectedPIDs.map((pid, index) => (
              <div key={index} className="flex items-center gap-2">
                <span 
                  className="w-3 h-3 rounded-sm"
                  style={{ backgroundColor: chartColors[index] }}
                />
                <select
                  value={pid}
                  onChange={(e) => {
                    const newPIDs = [...selectedPIDs];
                    newPIDs[index] = e.target.value;
                    setSelectedPIDs(newPIDs);
                  }}
                  className="bg-gray-700 text-white px-2 py-1 rounded text-sm"
                >
                  {availablePIDs.map(p => (
                    <option key={p} value={p}>{p}</option>
                  ))}
                </select>
              </div>
            ))}
          </div>
        </div>

        {/* Combined Chart */}
        <div className="flex-1 p-4">
          <Line
            options={{
              responsive: true,
              maintainAspectRatio: false,
              animation: false,
              plugins: {
                legend: { 
                  display: true,
                  labels: { color: '#9CA3AF' }
                }
              },
              scales: {
                x: { ticks: { color: '#9CA3AF' } },
                y: { ticks: { color: '#9CA3AF' } }
              }
            }}
            data={{
              datasets: selectedLogs.flatMap((log, logIndex) => 
                selectedPIDs.slice(0, 2).map((pid, pidIndex) => ({
                  label: `${log.file_name} - ${pid}`,
                  data: log.data?.map((row, i) => ({ x: i, y: row[pid] })) || [],
                  borderColor: chartColors[(logIndex * 2 + pidIndex) % chartColors.length],
                  pointRadius: 0,
                  borderWidth: logIndex === 0 ? 3 : 2
                }))
              )
            }}
          />
        </div>
      </div>
    );
  };

  if (loading && allLogs.length === 0) {
    return (
      <div className="h-screen flex items-center justify-center">
        <div className="text-gray-400 text-lg">Loading GPS data...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="h-screen flex items-center justify-center">
        <div className="text-red-400 text-lg">Error: {error}</div>
      </div>
    );
  }

  return (
    <>
      {/* Main Map Interface */}
      <div className="h-screen relative">
        {/* Map Container */}
        <MapContainer
          center={homeLocation ? [homeLocation.lat, homeLocation.lon] : [44.9778, -93.2650]}
          zoom={12}
          style={{ height: '100%', width: '100%' }}
          zoomControl={true}
        >
          <TileLayer
            url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}.png"
            attribution='&copy; CartoDB'
          />
          <HeatmapLayer heatData={heatmapData} intensity={Math.max(1, visibleLogs.length / 5)} />
        </MapContainer>

        {/* Semi-transparent overlay bar */}
        <div className="absolute top-0 left-0 right-0 bg-gray-900 bg-opacity-90 text-white p-4 z-[1000]">
          <div className="flex flex-wrap items-center gap-4">
            {/* Date filters */}
            <div className="flex items-center gap-2">
              <label className="text-sm text-gray-300">From:</label>
              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="bg-gray-700 text-white px-2 py-1 rounded text-sm"
              />
            </div>

            <div className="flex items-center gap-2">
              <label className="text-sm text-gray-300">To:</label>
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="bg-gray-700 text-white px-2 py-1 rounded text-sm"
              />
            </div>

            {/* Stats */}
            <div className="text-sm text-gray-300">
              Showing {visibleLogs.length} of {allLogs.length} logs
            </div>

            {/* Compare button */}
            <button
              onClick={handleCompareNow}
              disabled={selectedLogs.length === 0}
              className="bg-cyan-600 hover:bg-cyan-700 disabled:bg-gray-600 px-4 py-2 rounded font-medium"
            >
              Compare Now ({selectedLogs.length}/10)
            </button>
          </div>

          {/* Log list with selection */}
          <div className="mt-3 max-h-32 overflow-y-auto">
            <div className="text-xs text-gray-400 mb-1">
              Logs in current view (click to select for comparison):
            </div>
            <div className="flex flex-wrap gap-1">
              {visibleLogs.slice(0, 20).map(log => (
                <button
                  key={log.log_id}
                  onClick={() => handleLogSelect(log, !selectedLogs.find(l => l.log_id === log.log_id))}
                  className={`text-xs px-2 py-1 rounded ${
                    selectedLogs.find(l => l.log_id === log.log_id)
                      ? 'bg-cyan-600 text-white'
                      : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                  }`}
                >
                  {log.file_name.replace('.csv', '')}
                </button>
              ))}
              {visibleLogs.length > 20 && (
                <span className="text-xs text-gray-500">
                  +{visibleLogs.length - 20} more
                </span>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Comparison View Overlay */}
      {renderComparison()}
    </>
  );
}
